   768  int _libssh2_get_string(struct string_buf *buf, unsigned char **outbuf,
   769                          size_t *outlen)
   770  {
   771      uint32_t data_len;
   772      if(_libssh2_get_u32(buf, &data_len) != 0) {
   773          return -1;
   774      }
   775      if(!_libssh2_check_length(buf, data_len)) {
   776          return -1;
