   811  int _libssh2_get_bignum_bytes(struct string_buf *buf, unsigned char **outbuf,
   812                                size_t *outlen)
   813  {
   814      uint32_t data_len;
   815      uint32_t bn_len;
   816      unsigned char *bnptr;
   817
   818      if(_libssh2_get_u32(buf, &data_len)) {
   819          return -1;
   820      }
   821      if(!_libssh2_check_length(buf, data_len)) {
   822          return -1;
   823      }
   824
   825      bn_len = data_len;
   826      bnptr = buf->dataptr;
   827
   828      /* trim leading zeros */
   829      while(bn_len > 0 && *bnptr == 0x00) {
   830          bn_len--;
   831          bnptr++;
   832      }
   833
   834      *outbuf = bnptr;
   835      buf->dataptr += data_len;
   836
   837      if(outlen)
   838          *outlen = (size_t)bn_len;
   839
   840      return 0;
   841  }
